442	      }
443	      .hint {
444	        font-size: 12px;
445	      }
446	      .control-btn {
447	        padding: 14px 24px;
448	        font-size: 11px;
449	        min-height: 48px;
450	      }
451	    }
452	    @media (max-width: 480px) {
453	      body {
454	        gap: 12px;
455	        padding: 16px;
456	      }
457	      .mode-indicator {
458	        font-size: 9px;
459	      }
460	      .control-btn {
461	        padding: 14px 28px;
462	        min-width: 130px;
463	      }
464	    }
465	    @media (max-width: 360px) {
466	      body {
467	        gap: 10px;
468	        padding: 14px;
469	      }
