491	    @media (prefers-reduced-motion: reduce) {
492	      * {
493	        animation: none !important;
494	        transition: none !important;
495	      }
496	    }
497	    @supports (backdrop-filter: blur(0)) {
498	      .control-btn {
499	        background: rgba(255, 255, 255, 0.1);
