561	<body>
562	  <button type="button" class="help-btn" id="help-btn" aria-label="Show keyboard shortcuts" title="Help (press ?)">?</button>
563	
564	  <div class="modal" id="help-modal" role="dialog" aria-labelledby="modal-header" aria-modal="true">
565	    <div class="modal-content">
566	      <button type="button" class="modal-close" id="modal-close" aria-label="Close help">✕</button>
567	      <div class="modal-header" id="modal-header">Keyboard Shortcuts</div>
568	      <div class="modal-shortcuts">
569	        <div class="shortcut-item">
570	          <span class="shortcut-key">C</span>
571	          <span class="shortcut-desc">Cycle to next color</span>
572	        </div>
573	        <div class="shortcut-item">
574	          <span class="shortcut-key">X</span>
575	          <span class="shortcut-desc">Random color</span>
576	        </div>
577	        <div class="shortcut-item">
578	          <span class="shortcut-key">R</span>
579	          <span class="shortcut-desc">Reset to default</span>
580	        </div>
581	        <div class="shortcut-item">
582	          <span class="shortcut-key">Space</span>
583	          <span class="shortcut-desc">Toggle active state</span>
584	        </div>
585	        <div class="shortcut-item">
586	          <span class="shortcut-key">↩</span>
587	          <span class="shortcut-desc">Toggle active state</span>
588	        </div>
589	        <div class="shortcut-item">
590	          <span class="shortcut-key">Esc</span>
591	          <span class="shortcut-desc">Reset to default</span>
592	        </div>
593	        <div class="shortcut-item">
594	          <span class="shortcut-key">?</span>
