608	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
609	    <div class="controls" role="group" aria-label="Circle controls">
610	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
611	      <button type="button" class="control-btn" id="random-btn" aria-label="Jump to random color">Random</button>
612	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
613	    </div>
614	    <div class="keyboard-hint" aria-label="Keyboard shortcuts">Press <kbd>C</kbd> to cycle • <kbd>X</kbd> for random • <kbd>R</kbd> to reset • <kbd>?</kbd> for help</div>
615	  </main>
616	
617	  <script defer>
618	    (() => {
619	      const COLORS = [
620	        { class: 'default', name: 'Default White' },
621	        { class: 'color-mode-1', name: 'Pink' },
622	        { class: 'color-mode-2', name: 'Teal' },
623	        { class: 'color-mode-3', name: 'Mint' },
624	        { class: 'color-mode-4', name: 'Purple' },
625	        { class: 'color-mode-5', name: 'Orange' }
626	      ];
627	
628	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
629	      const isTouch = (() => {
630	        if (!window.matchMedia) return false;
631	        const hasCoarsePointer = window.matchMedia('(pointer:coarse)').matches;
632	        const hasTouchEvents = 'ontouchstart' in window;
633	        const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
634	        return hasCoarsePointer || hasTouchEvents || hasMaxTouchPoints;
635	      })();
636	
637	      const CONFIG = {
638	        storageKey: 'circle-state',
639	        tapDelay: 300,
640	        colorShiftDuration: 500,
641	        saveDebounceDuration: 100,
642	        keyDebounce: 50,
643	        isTouch
644	      };
645	
646	      const el = {
647	        circle: document.getElementById('decorative-circle'),
648	        hint: document.getElementById('hint-text'),
649	        modeIndicator: document.getElementById('mode-indicator'),
650	        cycleBtn: document.getElementById('cycle-btn'),
651	        randomBtn: document.getElementById('random-btn'),
652	        resetBtn: document.getElementById('reset-btn'),
653	        helpBtn: document.getElementById('help-btn'),
654	        helpModal: document.getElementById('help-modal'),
655	        modalClose: document.getElementById('modal-close')
656	      };
657	
658	      let state = { active: false, colorMode: 0 };
659	      let tapCount = 0;
660	      let tapTimeout = null;
661	      let animatingColorShift = false;
662	      let saveTimeout = null;
663	      let lastKeyTime = 0;
664	
665	      const haptic = (duration) => navigator.vibrate?.(duration);
666	
667	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
668	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
669	
670	      const storage = {
671	        save() {
672	          clearTimeout(saveTimeout);
673	          saveTimeout = setTimeout(() => {
674	            try {
675	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
676	            } catch (e) {
677	              if (e?.name === 'QuotaExceededError') {
678	                console.warn('Storage quota exceeded');
679	              }
680	            }
681	          }, CONFIG.saveDebounceDuration);
682	        },
683	        load() {
684	          try {
685	            const saved = localStorage.getItem(CONFIG.storageKey);
686	            if (saved) {
687	              const parsed = JSON.parse(saved);
688	              if (parsed?.active !== undefined && parsed?.colorMode !== undefined) {
689	                state = parsed;
690	              }
691	            }
692	          } catch (e) {
