737	      };
738	
739	      const modal = {
740	        previousFocus: null,
741	        open() {
742	          if (!el.helpModal || !el.modalClose) return;
743	          modal.previousFocus = document.activeElement;
744	          el.helpModal.classList.add('active');
745	          el.modalClose.focus();
746	          document.body.style.overflow = 'hidden';
747	        },
748	        close() {
749	          if (!el.helpModal) return;
750	          el.helpModal.classList.remove('active');
751	          document.body.style.overflow = '';
752	          modal.previousFocus?.focus?.();
753	        }
754	      };
755	
756	      const toggleActive = () => {
757	        state.active = !state.active;
758	        haptic(10);
759	        applyState();
760	        storage.save();
761	      };
762	
763	      const changeColor = (newMode, hapticPattern = 20) => {
764	        if (animatingColorShift || !el.circle) return;
765	        animatingColorShift = true;
766	        state.colorMode = newMode;
767	        state.active = true;
768	        haptic(hapticPattern);
769	        el.circle.classList.add('color-shifting');
770	        const timeoutId = setTimeout(() => {
771	          el.circle?.classList.remove('color-shifting');
772	          animatingColorShift = false;
773	        }, CONFIG.colorShiftDuration);
774	        applyState();
775	        storage.save();
776	        return timeoutId;
777	      };
778	
779	      const cycleColor = () => changeColor((state.colorMode + 1) % COLORS.length);
780	      const randomizeColor = () => changeColor(getRandomColorMode(), [20, 10, 20]);
781	
782	      const resetState = () => {
783	        state = { active: false, colorMode: 0 };
784	        haptic(10);
785	        applyState();
786	        storage.save();
787	      };
