807	      const keyHandlers = {
808	        ' ': toggleActive,
809	        'enter': toggleActive,
810	        'escape': resetState,
811	        'c': cycleColor,
812	        'x': randomizeColor,
813	        'r': resetState,
814	        '?': modal.open
815	      };
