817	      const handleKeyDown = (e) => {
818	        const key = e.key.toLowerCase();
819	        const handler = keyHandlers[key];
820	        if (!handler) return;
821	
822	        const now = Date.now();
823	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
824	
825	        e.preventDefault();
