828	          lastKeyTime = now;
829	        } catch (err) {
830	          console.error('Keyboard handler error:', err);
831	        }
832	      };
833	
834	      const handleModalKeyDown = (e) => {
835	        if (!el.helpModal?.classList.contains('active')) return;
836	
837	        if (e.key === 'Escape') {
838	          e.preventDefault();
839	          modal.close();
840	          return;
841	        }
842	
843	        if (e.key === 'Tab') {
844	          const focusableElements = Array.from(el.helpModal.querySelectorAll('button, [tabindex]'));
845	          if (focusableElements.length === 0) return;
846	
847	          const firstElement = focusableElements[0];
848	          const lastElement = focusableElements[focusableElements.length - 1];
849	          const activeElement = document.activeElement;
850	
851	          if (e.shiftKey) {
852	            if (activeElement === firstElement || !el.helpModal.contains(activeElement)) {
853	              e.preventDefault();
854	              lastElement?.focus();
855	            }
856	          } else {
857	            if (activeElement === lastElement || !el.helpModal.contains(activeElement)) {
858	              e.preventDefault();
859	              firstElement?.focus();
860	            }
861	          }
862	        }
863	      };
864	
865	      const handleModalBackdropClick = (e) => {
866	        if (e.target === el.helpModal) {
867	          modal.close();
868	        }
869	      };
870	
871	      const initListeners = () => {
872	        if (!el.circle) return;
873	
874	        el.circle.addEventListener('blur', () => {
875	          tapCount = 0;
876	          clearTimeout(tapTimeout);
877	        });
