886	          el.circle.addEventListener('dblclick', cycleColor, { passive: true });
887	        }
888	
889	        document.addEventListener('keydown', handleKeyDown);
890	
891	        el.cycleBtn?.addEventListener('click', cycleColor, { passive: true });
892	        el.randomBtn?.addEventListener('click', randomizeColor, { passive: true });
893	        el.resetBtn?.addEventListener('click', resetState, { passive: true });
894	        el.helpBtn?.addEventListener('click', modal.open, { passive: true });
895	        el.modalClose?.addEventListener('click', modal.close, { passive: true });
896	        el.helpModal?.addEventListener('click', handleModalBackdropClick, { passive: true });
897	        el.helpModal?.addEventListener('keydown', handleModalKeyDown);
898	      };
