const initListeners = () => {
  if (!el.circle) return;

  el.circle.addEventListener('blur', () => {
    tapCount = 0;
    clearTimeout(tapTimeout);
  });

  if (isTouch) {
    el.circle.addEventListener('touchend', handleTouchEnd, { passive: true });
    if (window.PointerEvent) {
      el.circle.addEventListener('pointerup', handleTouchEnd, { passive: true });
    }
  } else {
    el.circle.addEventListener('click', toggleActive, { passive: true });
    el.circle.addEventListener('dblclick', cycleColor, { passive: true });
  }

  document.addEventListener('keydown', handleKeyDown);

  el.cycleBtn?.addEventListener('click', cycleColor, { passive: true });
  el.randomBtn?.addEventListener('click', randomizeColor, { passive: true });
  el.resetBtn?.addEventListener('click', resetState, { passive: true });
  el.helpBtn?.addEventListener('click', modal.open, { passive: true });
  el.modalClose?.addEventListener('click', modal.close, { passive: true });
  el.helpModal?.addEventListener('click', handleModalBackdropClick, { passive: true });
  el.helpModal?.addEventListener('keydown', handleModalKeyDown);
};

